import json
from collections import defaultdict, Counter
from pathlib import Path
from src.viso_mmb import _build_proxy_predictions

ann_path = Path('VISO/coco/ship/Annotations/instances_test2017.json')
gt_payload = json.loads(ann_path.read_text())


def to_xyxy(b):
    x,y,w,h = b
    return (x,y,x+w,y+h)

def overlaps(a,b):
    ax1,ay1,ax2,ay2=a
    bx1,by1,bx2,by2=b
    return not (ax2 <= bx1 or bx2 <= ax1 or ay2 <= by1 or by2 <= ay1)

def inter(a,b):
    if not overlaps(a,b):
        return 0.0
    ax1,ay1,ax2,ay2=a
    bx1,by1,bx2,by2=b
    return max(0,min(ax2,bx2)-max(ax1,bx1))*max(0,min(ay2,by2)-max(ay1,by1))

seeds=[101,202,303,404,505]
fn_by_image = Counter()
fp_by_image = Counter()
for s in seeds:
    data = _build_proxy_predictions(gt_payload, seed=s, max_images=400)
    gt = data['ground_truth']
    preds = data['predictions']

    gt_map = defaultdict(list)
    for g in gt:
        gt_map[(g['image_id'], g['category_id'])].append({'bbox': to_xyxy(g['bbox']), 'matched': False})

    for p in sorted(preds, key=lambda x: x.get('score',1.0), reverse=True):
        key=(p['image_id'], p['category_id'])
        cands = gt_map.get(key, [])
        bi=-1; bo=0
        pb=to_xyxy(p['bbox'])
        for i,g in enumerate(cands):
            if g['matched']:
                continue
            ov = inter(pb, g['bbox'])
            if ov>bo:
                bo=ov; bi=i
        if bi>=0 and bo>0:
            cands[bi]['matched']=True
        else:
            fp_by_image[p['image_id']] += 1

    for (img_id,_cid), arr in gt_map.items():
        for g in arr:
            if not g['matched']:
                fn_by_image[img_id] += 1

print('top_fn_images', fn_by_image.most_common(10))
print('top_fp_images', fp_by_image.most_common(10))
print('images_with_any_fn', sum(1 for _k,v in fn_by_image.items() if v>0))
print('images_with_any_fp', sum(1 for _k,v in fp_by_image.items() if v>0))
