import json
from pathlib import Path
from collections import Counter

root = Path('VISO/coco/ship/Annotations')
train = json.loads((root / 'instances_train2017.json').read_text())
test = json.loads((root / 'instances_test2017.json').read_text())

train_imgs = train.get('images', [])
test_imgs = test.get('images', [])

train_ids = {int(i['id']) for i in train_imgs}
test_ids = {int(i['id']) for i in test_imgs}
train_files = {str(i.get('file_name', '')) for i in train_imgs}
test_files = {str(i.get('file_name', '')) for i in test_imgs}

id_overlap = sorted(train_ids & test_ids)
file_overlap = sorted(train_files & test_files)

# quick bbox fingerprint overlap check by file_name/category/bbox
train_map = {int(i['id']): str(i.get('file_name','')) for i in train_imgs}
test_map = {int(i['id']): str(i.get('file_name','')) for i in test_imgs}

def fp(ann, id_to_file):
    bbox = ann.get('bbox', [0,0,0,0])
    x,y,w,h = [round(float(v), 3) for v in bbox]
    return (id_to_file.get(int(ann['image_id']), ''), int(ann.get('category_id', -1)), x,y,w,h)

train_fps = {fp(a, train_map) for a in train.get('annotations', [])}
test_fps = {fp(a, test_map) for a in test.get('annotations', [])}
bbox_overlap = train_fps & test_fps

payload = {
    'dataset': 'VISO/coco/ship',
    'train_images': len(train_imgs),
    'test_images': len(test_imgs),
    'train_annotations': len(train.get('annotations', [])),
    'test_annotations': len(test.get('annotations', [])),
    'image_id_overlap_count': len(id_overlap),
    'file_name_overlap_count': len(file_overlap),
    'annotation_fingerprint_overlap_count': len(bbox_overlap),
    'sample_file_name_overlap': file_overlap[:10],
}
print(json.dumps(payload, indent=2))
