import json
from pathlib import Path

ann = Path('VISO/coco/ship/Annotations')
train = json.loads((ann / 'instances_train2017.json').read_text())
test = json.loads((ann / 'instances_test2017.json').read_text())

train_map = {int(i['id']): str(i.get('file_name', '')) for i in train['images']}
test_map = {int(i['id']): str(i.get('file_name', '')) for i in test['images']}

common = sorted(set(train_map) & set(test_map))
same_name = 0
diff_name = 0
samples_diff = []
for k in common:
    if train_map[k] == test_map[k]:
        same_name += 1
    else:
        diff_name += 1
        if len(samples_diff) < 10:
            samples_diff.append({'id': k, 'train': train_map[k], 'test': test_map[k]})

print(json.dumps({
    'common_ids': len(common),
    'same_file_name_for_same_id': same_name,
    'different_file_name_for_same_id': diff_name,
    'sample_different_name_collisions': samples_diff,
}, indent=2))
